var a=5;var i=[{id:`cooking-005-01`,theoryId:5,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which produce choice is generally better for a raw salad?`,ua:`Які овочі зазвичай краще обрати для сирого салату?`},explanation:{en:`Freshness and intact condition matter for flavor and food safety.`,ua:`Свіжість і цілісність продукту важливі для смаку та безпечності.`},options:[{id:`a`,text:{en:`Firm, sound produce without decay`,ua:`Пружні якісні овочі без ознак гниття`}},{id:`b`,text:{en:`Produce with visible mold`,ua:`Овочі з видимою пліснявою`}},{id:`c`,text:{en:`Cut vegetables held warm all day`,ua:`Нарізані овочі, що простояли весь день у теплі`}},{id:`d`,text:{en:`Anything that smells unusual`,ua:`Будь-що з нетиповим запахом`}}],answer:{optionIds:[`a`]}},{id:`cooking-005-02`,theoryId:5,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which factors should influence ingredient selection?`,ua:`Які чинники мають впливати на вибір інгредієнтів?`},explanation:{en:`Quality depends on fitness for use as well as safety and condition.`,ua:`Якість залежить від придатності до страви, безпечності й стану продукту.`},options:[{id:`a`,text:{en:`Ripeness appropriate for the dish`,ua:`Стиглість, що відповідає страві`}},{id:`b`,text:{en:`Seasonal availability`,ua:`Сезонна доступність`}},{id:`c`,text:{en:`Storage history and packaging integrity`,ua:`Історія зберігання та цілісність пакування`}},{id:`d`,text:{en:`The loudest packaging color`,ua:`Найяскравіший колір пакування`}}],answer:{optionIds:[`a`,`b`,`c`]}},{id:`cooking-005-03`,theoryId:5,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which shopping action is a food-safety mistake?`,ua:`Яка дія під час покупки є помилкою з погляду безпечності?`},explanation:{en:`Cut melon is perishable and must be handled under appropriate refrigeration.`,ua:`Нарізана диня швидко псується й потребує належного охолодження.`},options:[{id:`a`,text:{en:`Buy chilled pre-cut fruit from a refrigerator`,ua:`Купувати охолоджені нарізані фрукти з холодильника`}},{id:`b`,text:{en:`Inspect damaged packaging`,ua:`Перевіряти пошкоджене пакування`}},{id:`c`,text:{en:`Buy warm unrefrigerated cut melon for later use`,ua:`Купувати теплу нарізану диню без охолодження для подальшого споживання`}},{id:`d`,text:{en:`Select vegetables suited to the season`,ua:`Вибирати сезонні овочі`}}],answer:{optionIds:[`c`]}},{id:`cooking-005-04`,theoryId:5,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Two tomatoes are available: very ripe and delicate, or firm and less ripe. Which better fits a slow tomato sauce?`,ua:`Є два помідори: дуже стиглий і ніжний та твердий і менш стиглий. Який краще для соусу з довгим томлінням?`},explanation:{en:`Sound ripe tomatoes offer flavor and soften well in sauces; reject rotting fruit.`,ua:`Якісні стиглі помідори мають виразний смак і добре розм’якшуються в соусі; гнилі слід відбраковувати.`},options:[{id:`a`,text:{en:`The ripe tomato, provided it is sound and safe`,ua:`Стиглий помідор, якщо він якісний і безпечний`}},{id:`b`,text:{en:`The firm tomato is always safer`,ua:`Твердий помідор завжди безпечніший`}},{id:`c`,text:{en:`Both must be discarded`,ua:`Обидва потрібно викинути`}},{id:`d`,text:{en:`Choose by color of sticker only`,ua:`Обирати лише за кольором наліпки`}}],answer:{optionIds:[`a`]}}];var n={theoryId:5,exercises:i};export{n as default,i as exercises,a as theoryId};